 "content": "def transform(grid):
    """Stamp every all-zero occurrence of the shape marked by the nonbinary color."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row}
    marker_colors = colors - {0, 1}
    if not marker_colors:
        marker_colors = colors - {0, 5}
    marker = next(iter(marker_colors))
    points = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1

    matches = []
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(g[r+dr][c+dc] == 0 for dr, dc in shape):
                matches.append((r, c))
    for r, c in matches:
        for dr, dc in shape:
            g[r+dr][c+dc] = marker
    return g
